const page=`<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AFF Studio</title><style>body{font:16px system-ui;max-width:720px;margin:40px auto;background:#07131e;color:#eef;padding:20px}input,button{padding:10px;margin:5px}input{width:220px}button{background:#4ee1c1;border:0;border-radius:6px}#app{display:none}.row{border:1px solid #345;padding:10px;margin:7px 0}</style><main><h1>AFF Studio</h1><section id="auth"><h2>Đăng nhập</h2><input id="email" type="email" placeholder="Email"><input id="password" type="password" placeholder="Mật khẩu"><br><button onclick="login()">Đăng nhập</button><button onclick="register()">Đăng ký</button><p id="msg"></p></section><section id="app"><button onclick="logout()">Đăng xuất</button><h2>Sổ thu chi</h2><input id="kind" placeholder="chi hoặc thu" value="chi"><input id="category" placeholder="Đầu mục"><input id="amount" type="number" placeholder="Số tiền"><input id="date" type="date"><button onclick="add()">Lưu khoản</button><div id="rows"></div></section></main><script>date.value=new Date().toISOString().slice(0,10);async function api(p,b){let r=await fetch('/api/'+p,{method:b?'POST':'GET',headers:{'content-type':'application/json'},body:b?JSON.stringify(b):undefined});let j=await r.json();if(!r.ok)throw Error(j.error);return j}async function login(){try{await api('login',{email:email.value,password:password.value});ready()}catch(e){msg.textContent=e.message}}async function register(){try{await api('register',{email:email.value,password:password.value});ready()}catch(e){msg.textContent=e.message}}async function ready(){auth.style.display='none';app.style.display='block';rows.innerHTML=(await api('transactions')).map(x=>'<div class=row>'+x.entry_date+' · '+x.category+' · '+x.entry_type+' · '+x.amount+' ₫</div>').join('')}async function add(){await api('transactions',{entry_type:kind.value==='thu'?'income':'expense',category:category.value,amount:+amount.value,entry_date:date.value});ready()}async function logout(){await api('logout',{});location.reload()}fetch('/api/me').then(r=>r.ok&&ready())</script>`;
const json=(x,s=200,h={})=>new Response(JSON.stringify(x),{status:s,headers:{'content-type':'application/json',...h}});const id=()=>crypto.randomUUID();const b64=x=>btoa(String.fromCharCode(...new Uint8Array(x)));async function hash(p,s){return b64(await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(s),iterations:120000,hash:'SHA-256'},await crypto.subtle.importKey('raw',new TextEncoder().encode(p),'PBKDF2',false,['deriveBits']),256))}async function user(req,env){let t=(req.headers.get('cookie')||'').match(/aff_session=([^;]+)/)?.[1];if(!t)return null;return (await env.DB.prepare('SELECT u.id,u.email FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.id=? AND s.expires_at>datetime(\'now\')').bind(t).first())||null}export default{async fetch(req,env){let u=new URL(req.url),p=u.pathname;if(!p.startsWith('/api/'))return new Response(page,{headers:{'content-type':'text/html;charset=utf-8'}});let op=p.slice(5),b=req.method==='POST'?await req.json():{};if(op==='register'){if(!b.email||!b.password||b.password.length<8)return json({error:'Email và mật khẩu tối thiểu 8 ký tự'},400);let uid=id(),salt=id();try{await env.DB.prepare('INSERT INTO users(id,email,password_hash,password_salt) VALUES(?,?,?,?)').bind(uid,b.email.toLowerCase(),await hash(b.password,salt),salt).run()}catch{return json({error:'Email đã tồn tại'},409)}let sid=id();await env.DB.prepare('INSERT INTO sessions(id,user_id,expires_at) VALUES(?,?,datetime(\'now\',\'+30 days\'))').bind(sid,uid).run();return json({ok:true},200,{'set-cookie':'aff_session='+sid+'; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=2592000'})}if(op==='login'){let r=await env.DB.prepare('SELECT * FROM users WHERE email=?').bind((b.email||'').toLowerCase()).first();if(!r||await hash(b.password,r.password_salt)!==r.password_hash)return json({error:'Email hoặc mật khẩu không đúng'},401);let sid=id();await env.DB.prepare('INSERT INTO sessions(id,user_id,expires_at) VALUES(?,?,datetime(\'now\',\'+30 days\'))').bind(sid,r.id).run();return json({ok:true},200,{'set-cookie':'aff_session='+sid+'; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=2592000'})}let me=await user(req,env);if(op==='logout')return json({ok:true},200,{'set-cookie':'aff_session=; Max-Age=0; Path=/' });if(!me)return json({error:'Cần đăng nhập'},401);if(op==='me')return json(me);if(op==='transactions'&&req.method==='GET')return json({data:await env.DB.prepare('SELECT * FROM transactions WHERE user_id=? ORDER BY entry_date DESC').bind(me.id).all().then(x=>x.results)});if(op==='transactions'){let t=b.entry_type==='income'?'income':'expense';await env.DB.prepare('INSERT INTO transactions(id,user_id,entry_type,category,amount,entry_date) VALUES(?,?,?,?,?,?)').bind(id(),me.id,t,b.category,Math.round(b.amount),b.entry_date).run();return json({ok:true})}return json({error:'Not found'},404)}};
